<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';import {request,requestPage,errorText} from '../api';import type {Task} from '../types';import {kindNames,statusNames,displayTime,taskGroup} from '../domain';import Icon from '../components/Icon.vue';import Modal from '../components/Modal.vue';import TaskForm from '../components/TaskForm.vue';
const tasks=ref<Task[]>([]),filter=ref('active'),loading=ref(true),error=ref(''),editor=ref(false),selected=ref<Task>(),busy=ref('');const today=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
const cursor=ref<string|null>();async function load(more=false){loading.value=true;try{const result=await requestPage<Task>('/tasks?limit=200'+(more&&cursor.value?'&cursor='+encodeURIComponent(cursor.value):''));tasks.value=more?[...tasks.value,...result.data]:result.data;cursor.value=result.next_cursor;error.value='';}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
const active=computed(()=>tasks.value.filter(t=>!['done','cancelled'].includes(t.status))),todayCount=computed(()=>active.value.filter(t=>taskGroup(t)==='today').length),overdue=computed(()=>active.value.filter(t=>taskGroup(t)==='overdue').length);
const groups=computed(()=>{const definitions=filter.value==='done'?[['done','已经完成的努力']]:filter.value==='today'?[['overdue','需要留意'],['today','今天']]:[['overdue','需要留意'],['today','今天'],['upcoming','接下来'],['undated','时间待确定']];return definitions.map(([key,label])=>({key,label,items:tasks.value.filter(t=>taskGroup(t)===key)})).filter(g=>g.items.length);});
async function edit(task?:Task){try{selected.value=task?await request(`/tasks/${task.id}`):undefined;editor.value=true;}catch(e){error.value=errorText(e);}}
async function action(task:Task,name:string){busy.value=task.id;try{await request(`/tasks/${task.id}/${name}`,'POST',{expected_version:task.version});await load();}catch(e){error.value=errorText(e);}finally{busy.value='';}}
async function saved(){editor.value=false;await load();}
let refreshTimer:ReturnType<typeof setInterval>;
onMounted(()=>{load();refreshTimer=setInterval(()=>{if(!document.hidden&&!editor.value&&!busy.value&&!cursor.value&&!loading.value&&tasks.value.length<=200)load();},30000);});
onUnmounted(()=>clearInterval(refreshTimer));
</script>
<template><section class="page"><div class="page-eyebrow"><span class="tiny-line"/>{{today}}</div><div class="page-heading"><div><h1>把下一步，安排好<span class="accent-dot">。</span></h1><p>从一封通知，到一件完成的小事。</p></div><button class="button primary" @click="edit()"><Icon name="plus" :size="18"/>添加待办</button></div><div class="overview"><div class="overview-intro"><span class="overline">YOUR NEXT STEP</span><h3>重要的事，放在心上。<br>具体的时间，交给这里。</h3><span class="overview-caption"><Icon name="clock" :size="15"/>电脑运行时，为你按时提醒</span></div><div class="stat"><span>今日待办</span><strong>{{todayCount.toString().padStart(2,'0')}}</strong><small>一步一步，从容完成</small></div><div class="stat"><span>进行中的事项</span><strong>{{active.length.toString().padStart(2,'0')}}</strong><small><span v-if="overdue" class="text-orange">{{overdue}} 项需要留意</span><span v-else>你的下一站，正在靠近</span></small></div><span class="overview-decoration">↗</span></div><div class="section-toolbar"><div class="tabs"><button :class="{selected:filter==='active'}" @click="filter='active'">全部待办 <span>{{active.length}}</span></button><button :class="{selected:filter==='today'}" @click="filter='today'">今天</button><button :class="{selected:filter==='done'}" @click="filter='done'">已完成</button></div><button class="text-button" @click="load()">刷新列表</button></div><p v-if="error" class="error-box" role="alert">{{error}}</p><div v-if="loading" class="loading-block"><span class="spinner"/>正在整理你的待办…</div><div v-else-if="!groups.length" class="empty-state"><div class="empty-icon"><Icon name="leaf" :size="36"/></div><h3>{{filter==='done'?'每一次完成，都值得记录':'给下一步留个位置'}}</h3><p>{{filter==='done'?'完成的事项会保存在这里。':'添加一件待办，或者从收件识别中导入招聘邮件。'}}</p><button v-if="filter!=='done'" class="button" @click="edit()"><Icon name="plus" :size="17"/>创建第一件待办</button></div><div v-for="group in groups" :key="group.key" class="task-group"><h3 class="group-label">{{group.label}} <span>{{group.items.length}}</span><span v-if="group.key==='overdue'" class="group-caption">截止已过，请核对是否需要处理</span></h3><article v-for="task in group.items" :key="task.id" class="task-row" :class="{terminal:['done','cancelled'].includes(task.status)}"><button class="task-checkbox" :class="{checked:task.status==='done'}" :aria-label="task.status==='done'?'重新打开 '+task.title:'完成 '+task.title" :disabled="busy===task.id" @click="action(task,['done','cancelled'].includes(task.status)?'reopen':'complete')"><Icon v-if="task.status==='done'" name="check" :size="14"/></button><button class="task-main" @click="edit(task)"><h4>{{task.title}}<span v-if="task.priority===1" class="priority-dot" title="高优先级"/></h4><div class="task-meta"><span class="tag">{{kindNames[task.kind]??task.kind}}</span><span v-if="task.status==='in_progress'">进行中</span><span v-if="task.temporal?.needs_confirmation" class="text-orange">时间待确认</span><span v-else-if="task.next_reminder_at">已安排提醒</span><span v-else>本地待办</span></div></button><div class="task-date" :class="{'text-orange':group.key==='overdue'}"><span>{{task.due_date??displayTime(task.starts_at??task.due_at)}}</span><small>{{task.due_date?'具体时刻待确认':statusNames[task.status]??task.status}}</small></div><button v-if="!['done','cancelled'].includes(task.status)" class="text-button cancel-task" :disabled="busy===task.id" @click="action(task,'cancel')">取消事项</button><button class="icon-button" aria-label="编辑待办" @click="edit(task)"><Icon name="chevron" :size="18"/></button></article></div><div v-if="cursor" class="button-row"><button class="button" :disabled="loading" @click="load(true)">加载更多待办</button></div><div class="quiet-tip"><Icon name="leaf" :size="17"/><span>不必一次完成所有事，先把眼前这一件做好。</span></div></section><Modal v-if="editor" :title="selected?'编辑待办':'添加一件待办'" @close="editor=false"><TaskForm :task="selected" @saved="saved" @cancel="editor=false"/></Modal></template>
